using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = _app.Services.GetRequiredService<IChatClient>();
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        await _app.DisposeAsync();
        await _appHost.DisposeAsync();
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        return new ReportingConfiguration(
            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "evaluation-results"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfiguration: new ChatConfiguration(_evaluatorClient));
    }

    [TestMethod]
    public async Task Chat_Response_MeetsQualityThresholds()
    {
        var reportingConfig = CreateReportingConfiguration();
        await using var scenario = await reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_Response_MeetsQualityThresholds));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await scenario.EvaluateAsync(messages, response);

        foreach (var metric in scenario.GetAllMetrics())
        {
            if (metric is NumericMetric numericMetric)
            {
                Assert.IsTrue(
                    numericMetric.Value >= 3,
                    $"Metric '{metric.Name}' scored {numericMetric.Value}, expected >= 3");
            }
        }
    }

    [TestMethod]
    public async Task Chat_Response_IsRelevantToPrompt()
    {
        var reportingConfig = CreateReportingConfiguration();
        await using var scenario = await reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_Response_IsRelevantToPrompt));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how photosynthesis works in two sentences.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await scenario.EvaluateAsync(messages, response);

        var relevance = scenario.GetAllMetrics()
            .OfType<NumericMetric>()
            .FirstOrDefault(m => m.Name == "Relevance");

        Assert.IsNotNull(relevance, "Relevance metric should be present");
        Assert.IsTrue(
            relevance.Value >= 4,
            $"Relevance scored {relevance.Value}, expected >= 4");
    }

    [TestMethod]
    public async Task Chat_MultiTurn_MaintainsCoherence()
    {
        var reportingConfig = CreateReportingConfiguration();
        await using var scenario = await reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_MultiTurn_MaintainsCoherence));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is machine learning?")
        };

        var firstResponse = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(firstResponse.Messages);

        messages.Add(new ChatMessage(ChatRole.User, "Can you give me a simple example of it?"));

        var secondResponse = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(secondResponse.Messages);

        await scenario.EvaluateAsync(messages, secondResponse);

        var coherence = scenario.GetAllMetrics()
            .OfType<NumericMetric>()
            .FirstOrDefault(m => m.Name == "Coherence");

        Assert.IsNotNull(coherence, "Coherence metric should be present");
        Assert.IsTrue(
            coherence.Value >= 3,
            $"Coherence scored {coherence.Value}, expected >= 3");
    }
}

